   595  ymd_to_days (gint year,
   596               gint month,
   597               gint day)
   598  {
   599    gint64 days;
   600
   601    days = ((gint64) year - 1) * 365 + ((year - 1) / 4) - ((year - 1) / 100)
   602        + ((year - 1) / 400);
   603
   604    days += days_in_year[0][month - 1];
